; rcount.asm -- chapter 7: R counts opcode fetches
; generated by gen07.py
        INCLUDE "msx.inc"
        OUTPUT "rcount.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
        ld a, $7E
        ld r, a                 ; R = $7E
        ld hl, RESULTS + 0
        ld b, 8
read0:  ld a, r                  ; 2 opcode fetches (ED 5F)
        ld (hl), a              ; 1
        inc hl                  ; 1
        djnz read0             ; 1: five a turn
        ld a, $FE
        ld r, a                 ; R = $FE
        ld hl, RESULTS + 8
        ld b, 8
read1:  ld a, r                  ; 2 opcode fetches (ED 5F)
        ld (hl), a              ; 1
        inc hl                  ; 1
        djnz read1             ; 1: five a turn
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
